// === Tab: mySketch ===
let discoBall
let fbo
let renderer
let starburst
let bg
let cam

function setup() {
	renderer = createCanvas(800, 800, WEBGL)
	pixelDensity(1)

	let bgFbo = createFramebuffer({ width: 600, height: 300, density: 3 })
	bgFbo.begin()
	background(0)
	fill(255, 100)
	noStroke()
	for (let i = 0; i < 150; i++) {
		circle(
			random(-bgFbo.width/2+15, bgFbo.width/2-15),
			random(-bgFbo.height/2+15, bgFbo.height/2-15),
			random() < 0.2 ? 15 : 5
		)
	}
	filter(BLUR, 2)
	bgFbo.end()
	bg = bgFbo.get()
	bgFbo.remove()

	fbo = createFramebuffer()
	cam = fbo.createCamera()
	discoBall = baseMaterialShader().modify(() => {
		let objPos = sharedVec3()
		getObjectInputs((inputs) => {
			objPos = inputs.position
			return inputs
		})

		const uN1 = uniformVec3();
		const uN2 = uniformVec3();
		const uN3 = uniformVec3();
		getPixelInputs((inputs) => {
			const x = objPos.x
			const y = objPos.y
			const z = objPos.z
			const origNormal = normalize(objPos)

			const r = 1
			let theta = acos(-y / r)
			let phi = 0
			if (x !== 0 && z !== 0) {
				phi = sign(z) * acos(x / sqrt(x * x + z * z))
			}

			let origTheta = theta

			const angLenY = PI * 0.035
			const angLenX = angLenY // PI * mix(0.035, 0.1, abs(y))
			if (theta <= 0) {
				theta = ceil(theta / angLenY) * angLenY - angLenY/2
			} else {
				theta = floor(theta / angLenY) * angLenY + angLenY/2
			}

			if (fract(theta/angLenY / 2) < 0.5) {
				phi += angLenX * 0.5
			}
			let origPhi = phi

			if (phi <= 0) {
				phi = ceil(phi / angLenX) * angLenX - angLenX/2
			} else {
				phi = floor(phi / angLenX) * angLenX + angLenX/2
			}

			let edge = smoothstep(
				0.4,
				0.5,
				max(abs(origTheta-theta)/angLenY, abs(origPhi-phi)/angLenX)
			)
			inputs.shininess = mix(400, 100, edge)
			inputs.color = mix([0.5, 0.5, 0.5, 1], [0, 0, 0, 1], edge)
			inputs.ambientMaterial = inputs.color.rgb

			let newNormal = [
				r * sin(theta) * cos(phi),
				r * cos(theta),
				r * sin(theta) * sin(phi)
			]

			let normal = newNormal
			normal = [
				dot(uN1, normal),
				dot(uN2, normal),
				dot(uN3, normal),
			]

			inputs.normal = normal

			return inputs
		})
	})

	starburst = baseFilterShader().modify(() => {
		let size = uniformVec2(() => [width, height])
		getColor((inputs, canvasContent) => {
			let b = 0
			noiseDetail(2, 0.5)
			let rOff = abs(noise(inputs.texCoord * size))
			for (let i = 0; i < 6; i++) {
				let angle = i/6 * TWO_PI
				for (let rad = 0; rad < 5; rad++) {
					let off = [
						cos(angle),
						sin(angle)
					] * (rad + rOff) * 20 / size
					let sample = getTexture(canvasContent, inputs.texCoord + off)
					let sampleBrightness = max(sample.r, max(sample.g, sample.b))
						* (1 - rad/5)
					b = max(b, sampleBrightness)
				}
			}
			return [b, b, b, 1]
		})
	})
}

function draw() {
	const t = millis()

	fbo.begin()
	background(0)
	setCamera(cam)
	cam.camera(
		800*cos(t * 0.0001),
		0,
		800*sin(t * 0.0001),
		0,
		0,
		0
	)
	panorama(bg)
	imageLight(bg)
	// orbitControl()
	// lights()

	push()
	metalness(400)
	specularMaterial(255)
	shininess(400)
	directionalLight(255, 255, 255, -1, 0.5, -0.5)
	directionalLight(255, 255, 255, 0.2, 0, 1)
	directionalLight(255, 255, 255, -0.2, 0, 1)
	const s1 = abs(sin(t * 0.005))
	directionalLight(s1*255, 0, s1*255, 0, 1, 0)
	const s2 = abs(sin(t * 0.005 + PI/2))
	directionalLight(0, 0, s2*255, 1, -1, 0)
	spotLight(color(255), 0, 2000, 0, 0, -1, 0)
	for (let i = 0; i < 5; i++) {
		pointLight(
			255, 255, 255,
			sin(i*Math.E + t*0.00009)*400, sin(i*Math.E/2 + t*0.00009)*400, 400)
	}
	rotateY(t * 0.0005)
	// rotate(sin(t * 0.0003) * PI * 0.05)
	renderer.scratchMat3.inverseTranspose4x4(renderer.uMVMatrix)
	const m = renderer.scratchMat3.mat3
	discoBall.setUniform("uN1", [m[0], m[3], m[6]])
	discoBall.setUniform("uN2", [m[1], m[4], m[7]])
	discoBall.setUniform("uN3", [m[2], m[5], m[8]])
	shader(discoBall)
	noStroke()
	sphere(200)
	pop()
	fbo.end()

	imageMode(CENTER)
	image(fbo, 0, 0)
	fbo.draw(() => {
		filter(starburst)
		// filter(BLUR, 1)
	})
	push()
	blendMode(ADD)
	tint(255, 100)
	image(fbo, 0, 0)
	pop()
}

